// lib/middlewares.mjs — a corrente de middlewares do sistema.

// Aplica os middlewares na ordem, passando o resultado de um para o próximo.
// Cada middleware devolve o req (novo ou alterado) — o original só muda se
// algum middleware mexer nele de propósito.
export function aplicarPipeline(req, middlewares) {
  if (!Array.isArray(middlewares)) {
    throw new Error('lista de middlewares inválida');
  }
  let atual = req;
  for (const middleware of middlewares) {
    atual = middleware(atual);
    if (atual === undefined || atual === null) {
      throw new Error('middleware não retornou o req');
    }
  }
  return atual;
}

// Marca o req como JSON: devolve um objeto novo com o tipo de conteúdo.
export function marcarTipoJson(req) {
  return { metodo: req.metodo, caminho: req.caminho, tipoConteudo: 'application/json' };
}

// Registra o acesso no log e devolve o req para a cadeia continuar.
export function registrarAcesso(req, registros) {
  if (!Array.isArray(registros)) {
    throw new Error('registros inválidos');
  }
  registros.push(req.metodo + ' ' + req.caminho);
  return req;
}

