// lib/rota.mjs — o roteador SIMULADO: recebe o pedido e devolve a resposta.
import { aplicarPipeline, marcarTipoJson, registrarAcesso } from './middlewares.mjs';
import { montarJson, naoEncontrado } from './respostas.mjs';

export function atenderPedido(catalogo, pedido, registros) {
  if (!Array.isArray(catalogo)) throw new Error('catálogo inválido');
  if (typeof pedido !== 'object' || pedido === null) throw new Error('pedido inválido');
  if (!Array.isArray(registros)) throw new Error('registros inválidos');

  const req = aplicarPipeline(pedido, [marcarTipoJson, (r) => registrarAcesso(r, registros)]);

  if (req.metodo === 'GET' && req.caminho === '/livros') {
    return { status: 200, tipoConteudo: req.tipoConteudo, corpo: JSON.stringify(catalogo) };
  }

  // '/livros/1' vira ['', 'livros', '1'] — o id fica na posição 2.
  const partes = req.caminho.split('/');
  if (req.metodo === 'GET' && partes[1] === 'livros' && partes[2] !== undefined) {
    const id = Number(partes[2]);
    const livro = catalogo.find((l) => l.id === id);
    return livro ? montarJson(200, livro) : naoEncontrado();
  }

  return montarJson(405, { erro: 'método não permitido' });
}

