import { test } from 'node:test';
import assert from 'node:assert/strict';
import { aplicarPipeline, marcarTipoJson, registrarAcesso } from './lib/middlewares.mjs';
import { montarJson, naoEncontrado } from './lib/respostas.mjs';
import { atenderPedido } from './lib/rota.mjs';

const catalogo = [
  { id: 1, titulo: 'Dom Casmurro', autor: 'Machado de Assis' },
  { id: 2, titulo: 'O Cortiço', autor: 'Aluísio Azevedo' },
];

test('aplicarPipeline aplica os middlewares em ordem sem mudar o original', () => {
  const original = { metodo: 'GET', caminho: '/livros' };
  const resultado = aplicarPipeline(original, [marcarTipoJson, (r) => ({ ...r, logado: true })]);
  assert.deepEqual(resultado, { metodo: 'GET', caminho: '/livros', tipoConteudo: 'application/json', logado: true });
  assert.deepEqual(original, { metodo: 'GET', caminho: '/livros' });
  assert.throws(() => aplicarPipeline(original, [(r) => undefined]), /middleware não retornou o req/);
  assert.throws(() => aplicarPipeline(original, 'não é lista'), /lista de middlewares inválida/);
});

test('marcarTipoJson adiciona o tipo de conteúdo ao req', () => {
  assert.deepEqual(marcarTipoJson({ metodo: 'GET', caminho: '/livros' }), {
    metodo: 'GET',
    caminho: '/livros',
    tipoConteudo: 'application/json',
  });
});

test('registrarAcesso guarda a entrada no log e valida a lista', () => {
  const registros = [];
  const req = registrarAcesso({ metodo: 'GET', caminho: '/livros/2' }, registros);
  assert.deepEqual(registros, ['GET /livros/2']);
  assert.deepEqual(req, { metodo: 'GET', caminho: '/livros/2' });
  assert.throws(() => registrarAcesso({ metodo: 'GET', caminho: '/' }, null), /registros inválidos/);
});

test('montarJson e naoEncontrado montam as respostas JSON padrão', () => {
  assert.deepEqual(montarJson(201, { ok: true }), {
    status: 201,
    tipoConteudo: 'application/json',
    corpo: '{"ok":true}',
  });
  assert.deepEqual(naoEncontrado(), {
    status: 404,
    tipoConteudo: 'application/json',
    corpo: '{"erro":"livro não encontrado"}',
  });
});

test('GET /livros devolve 200 com JSON e registra o acesso pelo pipeline', () => {
  const registros = [];
  const pedido = { metodo: 'GET', caminho: '/livros' };
  const resposta = atenderPedido(catalogo, pedido, registros);
  assert.equal(resposta.status, 200);
  assert.equal(resposta.tipoConteudo, 'application/json');
  assert.equal(resposta.corpo, JSON.stringify(catalogo));
  assert.deepEqual(registros, ['GET /livros']);
  assert.deepEqual(pedido, { metodo: 'GET', caminho: '/livros' });
});

test('GET /livros/:id devolve o livro ou 404; o resto devolve 405', () => {
  const registros = [];
  const achado = atenderPedido(catalogo, { metodo: 'GET', caminho: '/livros/1' }, registros);
  assert.equal(achado.status, 200);
  assert.equal(achado.corpo, JSON.stringify(catalogo[0]));

  const faltando = atenderPedido(catalogo, { metodo: 'GET', caminho: '/livros/99' }, registros);
  assert.equal(faltando.status, 404);
  assert.equal(faltando.corpo, '{"erro":"livro não encontrado"}');

  const proibido = atenderPedido(catalogo, { metodo: 'POST', caminho: '/livros' }, registros);
  assert.equal(proibido.status, 405);

  assert.deepEqual(registros, ['GET /livros/1', 'GET /livros/99', 'POST /livros']);
});
